// Made-up sample for "Try a sample file": a small Edge Collections database built by _build/make-sample.mjs from
// _tests/fixtures.mjs (sampleSpec). Every title, address and note in it is invented; the addresses use example domains.
const B64 = '';
export function sampleBytes() {
  const bin = atob(B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
